Solution
不妨放宽限制总是构造 \(n=5000\)。
传 \(4999\) 条边，至少保留 \(2500\) 条边。我们需要让任意 \(2500\) 条边都能恢复出 \(X\)。
需要用任意若干个元素还原完整信息。我们不能要求任意保留下来的边都能独立承载完整信息，从而抵抗任意的边删除。自然想到多项式。
不妨先对 \(X\) 拆位，从高到低拆成 \(12\) 个 \(5\) 位二进制数，每个数是 \([0,32)\) 的整数。把它们作为多项式系数，得到一个 \(11\) 次多项式 \(F(x)\)。
不妨令每个点父亲的编号都严格小于它。取质数模数 \(m=101\)，\(1\) 为根，构造 \(3\) 层的树。其中第二层的点是 \([2,m+1]=[2,102]\)，第三层则是 \([103,5000]\)。
对于每个第三层的点 \(u\in [103,5000]\)，我们令 \(\mathrm{fa}_u = 2+F(u)\bmod m\)。这样每条连接二、三两层的边都传一个点值。
倒回来只需要点值转系数即可。
显然至少保留 \(12\) 个模 \(m\) 意义下互不相同的点值，足够通过本题。
Code
Alice.cpp
#include "Alice.h"
#include <bits/stdc++.h>
#define rep(i,a,b) for(int i(a);i<b;++i)
#define per(i,a,b) for(int i(a);i>b;--i)
#define rept(i,a,b) for(int i(a);i<=b;++i)
#define pert(i,a,b) for(int i(a);i>=b;--i)
#define ll long long
#define pii pair<int,int>
using namespace std;
namespace{
    constexpr int N=5000,L=5,K=12,M=101;
    int a[K];
    vector<pii> g;
}
vector<pii> Alice(){
    g.clear();
    ll x=setN(N);
    rep(i,0,K){
        a[i]=x&((1<<L)-1);
        x>>=L;
    }
    rept(i,2,M+1) g.emplace_back(1,i);
    rept(i,M+2,N){
        int y=0;
        pert(j,K-1,0) y=(y*i+a[j])%M;
        g.emplace_back(y+2,i);
    }
    return g;
}

Bob.cpp
#include "Bob.h"
#include <bits/stdc++.h>
#define rep(i,a,b) for(int i(a);i<b;++i)
#define per(i,a,b) for(int i(a);i>b;--i)
#define rept(i,a,b) for(int i(a);i<=b;++i)
#define pert(i,a,b) for(int i(a);i>=b;--i)
#define ll long long
#define pii pair<int,int>
using namespace std;
namespace{
    constexpr int N=5000,L=5,K=12,M=101;
    int a[K],x[K],y[K],h[K],cnt=0;
    bool f[M];
    int ksm(int x,int y){
        int res=1;
        while(y){
            if(y&1) (res*=x)%=M;
            (x*=x)%=M,y>>=1;
        }
        return res;
    }
}
ll Bob(vector<pii> V){
    cnt=0;
    fill(a,a+K,0);
    fill(f,f+K,0);
    for(auto [u,v]:V){
        assert(u<v);
        if(v>=M+2){  // 有效点值
            u-=2,v%=M;
            if(!f[v]){
                x[cnt]=v,y[cnt++]=u;
                f[v]=true;
                if(cnt==K) break;
            }
        }
    }
    rep(i,0,K){  // 点值转系数
        int mul=1;
        rep(j,0,K) if(j^i) (mul*=x[i]-x[j])%=M;
        mul=ksm(mul,M-2)*y[i]%M;
        fill(h,h+K,0);
        h[0]=1;
        rep(j,0,K) if(j^i){
            pert(k,K-2,0){
                (h[k+1]+=h[k])%=M;
                (h[k]*=-x[j])%=M;
            }
        }
        rep(j,0,K) (a[j]+=mul*h[j])%=M;
    }
    ll ans=0;
    pert(i,K-1,0) ans=(ans<<L)|((a[i]+M)%M);
    return ans;
}
